(function(){function draw(g){if(!g||g.__waveDrawn)return;g.__waveDrawn=true;var svg=g.closest('svg');if(svg){svg.setAttribute('viewBox','0 0 1440 800');svg.setAttribute('preserveAspectRatio','xMidYMid slice');}var NS='http://www.w3.org/2000/svg';g.setAttribute('fill','none');g.setAttribute('stroke','#F4F0EC');g.setAttribute('stroke-width','0.75');g.setAttribute('stroke-opacity','0.5');g.setAttribute('stroke-linecap','round');g.setAttribute('vector-effect','non-scaling-stroke');var N=40,S=60,OX=-160,OY=600,XE=1520,P=2.4,A=16,WL=460,SP=0.0004,SS=36;var H=[],paths=[],i;for(i=0;i<N;i++){var t=i/(N-1);H.push(60+(1-Math.log(1+(1-t)*(Math.E-1)))*1320);}for(i=0;i<N;i++){var p=document.createElementNS(NS,'path');p.setAttribute('vector-effect','non-scaling-stroke');g.appendChild(p);paths.push(p);}var st=performance.now();function fr(now){var tm=(now-st)*SP,li,s;for(li=0;li<N;li++){var h=H[li],ys=(li/(N-1))*SS,ph=li*0.22,d='';for(s=0;s<=S;s++){var ts=s/S,x=OX+ts*(XE-OX),am=A*Math.sin(ts*Math.PI),y=OY-ys*(1-ts)-h*Math.pow(ts,P)+am*Math.sin((x/WL)*6.2832+ph+tm);d+=(s?' L ':'M ')+x.toFixed(1)+' '+y.toFixed(1);}paths[li].setAttribute('d',d);}requestAnimationFrame(fr);}requestAnimationFrame(fr);}function scan(){document.querySelectorAll('.pa-hero-wave g').forEach(draw);}function boot(){scan();try{new MutationObserver(scan).observe(document.documentElement,{childList:true,subtree:true});}catch(e){}setTimeout(scan,300);setTimeout(scan,1000);setTimeout(scan,2500);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot);}else{boot();}window.addEventListener('load',scan);})();